// Render the dev-flows-base plugin's flow files and front-end wrapper
// templates (this package), and the dev-flows front ends' wrapper skills
// (plugins/dev-flows, plugins/dev-flows-cursor, plugins/dev-flows-codex,
// plugins/dev-flows-amp, with the index.js that registers Amp's skills). With --check,
// write nothing and fail when a generated file is stale or a file in a
// generated directory isn't generated any more, so CI catches a flow edited
// without regenerating, generated output edited by hand, or a removed flow
// whose files were left behind.

import fs from "node:fs"
import path from "node:path"
import { type GeneratedFile, writeGeneratedFiles } from "@agent-flows/core"
import {
  DEV_FLOWS_FRONT_ENDS,
  renderAmpPluginIndex,
  renderBase,
  renderDevFlowsFrontEnd,
  renderFrontEndTemplates,
} from "../src/flows/index.ts"

const check = process.argv.includes("--check")
const packageDir = path.resolve(import.meta.dirname, "..")
const repoDir = path.resolve(packageDir, "..", "..")

interface Output {
  rootDir: string
  /** Directories holding only generated files, relative to rootDir. */
  generatedDirs: string[]
  files: GeneratedFile[]
}

const outputs: Output[] = [
  {
    rootDir: packageDir,
    generatedDirs: ["flows"],
    files: [...renderBase(), ...renderFrontEndTemplates()],
  },
  ...DEV_FLOWS_FRONT_ENDS.map(({ host, dir }) => {
    const skills = renderDevFlowsFrontEnd(host)
    return {
      rootDir: path.join(repoDir, "plugins", dir),
      generatedDirs: ["skills"],
      files:
        host === "amp" ? [...skills, renderAmpPluginIndex(skills)] : skills,
    }
  }),
]

function listFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    return []
  }
  return fs
    .readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => path.join(entry.parentPath, entry.name))
}

let changedCount = 0
let unchangedCount = 0
let orphanCount = 0
for (const { rootDir, generatedDirs, files } of outputs) {
  const shown = path.relative(repoDir, rootDir)
  const { changed, unchanged } = writeGeneratedFiles(files, { rootDir, check })
  for (const file of changed) {
    console.log(`[build-skills] ${check ? "stale" : "wrote"} ${shown}/${file}`)
  }
  changedCount += changed.length
  unchangedCount += unchanged

  const expected = new Set(
    files.map((file) => path.resolve(rootDir, file.path)),
  )
  for (const dir of generatedDirs) {
    for (const file of listFiles(path.join(rootDir, dir))) {
      if (expected.has(file)) {
        continue
      }
      orphanCount += 1
      const name = path.relative(repoDir, file)
      if (check) {
        console.log(`[build-skills] not generated: ${name}`)
      } else {
        fs.rmSync(file)
        console.log(`[build-skills] removed ${name}`)
      }
    }
  }
}

if (check && changedCount + orphanCount > 0) {
  console.error(
    `[build-skills] ${changedCount} generated file(s) out of date, ${orphanCount} not generated by any flow. Run \`bun run build\` in packages/dev and commit the result.`,
  )
  process.exit(1)
}
console.log(
  `[build-skills] ${changedCount} ${check ? "stale" : "written"}, ${orphanCount} ${check ? "extra" : "removed"}, ${unchangedCount} unchanged`,
)
